// Some portions generated by Claude

// .agent/execplans/workbench-shared-result-table.md: one RDF result table (workbench.queryStream.ResultTable) for the
// Query page's results, Explore, the Export preview and the Remove preview.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { FakeDocument } = require('./browser-fakes.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');
const { renderPageResultTables, resultTableHosts, settle } = require('./page-result-table-harness.js');

const scripts = process.env.WORKBENCH_SCRIPT_DIR
    || path.resolve(__dirname, '../../tools/workbench/src/main/webapp/scripts');

function loadWorkbench() {
    const window = {};
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, window, workbench, setTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), context, { filename });
    }
    window.workbench = context.workbench;
    return context.workbench;
}

const XSD = 'http://www.w3.org/2001/XMLSchema#';
const iri = value => ({ kind: 'iri', value });
const context = { basePath: '/rdf4j-workbench', repositoryId: 'a', workbench: {} };

/** A ResultTable over rows in a fake document whose elements are width pixels wide. */
function standaloneTable(workbench, rows, variables, options = {}, width = 1200) {
    const document = new FakeDocument();
    const createElement = document.createElement.bind(document);
    document.createElement = tagName => {
        const element = createElement(tagName);
        element.clientWidth = width;
        return element;
    };
    const root = document.createElement('div');
    document.body.appendChild(root);
    const table = new workbench.queryStream.ResultTable(root, {
        rowCount: () => rows.length,
        variables: () => variables,
        read: async (start, count) => rows.slice(start, start + count),
        namespaces: () => [{ prefix: 'xsd', name: XSD }, { prefix: 'ex', name: 'http://example.org/' }]
    }, options);
    return { document, root, table };
}

function cellsOf(row) {
    return row.children.filter(child => child.tagName === 'TD');
}

test('a shared result table names its columns, labels its cells and says what an empty value means', async () => {
    const workbench = loadWorkbench();
    const rows = [
        [iri('http://example.org/a'), { kind: 'literal', value: '2026-10-05', datatype: XSD + 'date' }, null],
        [iri('http://example.org/b'), { kind: 'literal', value: 'hallo', language: 'de' }, iri('http://example.org/g')]
    ];
    const labels = { subject: 'Subject', object: 'Object', context: 'Graph' };
    const { root, table } = standaloneTable(workbench, rows, ['subject', 'object', 'context'], {
        label: 'Statements',
        columnLabel: name => labels[name],
        cellLabel: name => labels[name],
        unboundLabel: name => name === 'context' ? 'Default graph' : '',
        rowAttributes: index => ({ 'data-workbench-row-index': String(index + 10) })
    });
    await table.render();
    assert.equal(root.getAttribute('data-effective-layout'), 'table');
    assert.equal(table.table.getAttribute('aria-label'), 'Statements');
    assert.deepEqual(table.table.querySelectorAll('thead th').map(cell => cell.textContent),
        ['Subject', 'Object', 'Graph']);
    const body = table.tableBody.children;
    assert.deepEqual(body.map(row => row.getAttribute('data-workbench-row-index')), ['10', '11']);
    assert.deepEqual(body.map(row => row.getAttribute('data-query-row-index')), ['0', '1']);
    const first = cellsOf(body[0]);
    assert.deepEqual(first.map(cell => cell.getAttribute('data-label')), ['Subject', 'Object', 'Graph']);
    assert.equal(first[2].textContent, 'Default graph', 'the unbound graph is the default graph');
    assert.ok(!first[2].getAttribute('aria-label'), 'a named empty value is not announced as "Unbound"');
    assert.equal(first[0].querySelector('a').querySelectorAll('wbr').length, 1, 'IRIs may break after their colon');
    assert.equal(first[1].querySelector('.rdf-datatype').textContent, 'xsd:date');
    assert.equal(cellsOf(body[1])[1].querySelector('.rdf-language').textContent, '@de');

    table.setShowDatatypes(false);
    await table.render();
    assert.equal(cellsOf(table.tableBody.children[0])[1].querySelector('.rdf-datatype'), null,
        'Show datatypes off renders the cells again without datatype tags');
    table.dispose();
});

test('a shared result table without owner labels keeps the Query page cells', async () => {
    const workbench = loadWorkbench();
    const { table } = standaloneTable(workbench, [[null]], ['value']);
    await table.render();
    const cell = cellsOf(table.tableBody.children[0])[0];
    assert.equal(cell.getAttribute('data-label'), 'value');
    assert.equal(cell.textContent, '—');
    assert.equal(cell.getAttribute('aria-label'), 'Unbound');
    assert.equal(table.table.querySelectorAll('thead th')[0].textContent, 'value');
    table.dispose();
});

test('a shared result table too wide for its columns shows records, with the same cells', async () => {
    const workbench = loadWorkbench();
    const { root, table } = standaloneTable(workbench, [[iri('http://example.org/a'), null]], ['subject', 'context'],
        { unboundLabel: () => 'Default graph', rowAttributes: index => ({ 'data-workbench-row-index': String(index) }) },
        120);
    await table.render();
    assert.equal(root.getAttribute('data-effective-layout'), 'records');
    const record = table.records.children.find(child => child.tagName === 'ARTICLE');
    assert.equal(record.getAttribute('data-workbench-row-index'), '0');
    assert.deepEqual(record.querySelectorAll('dt').map(key => key.textContent), ['subject', 'context']);
    assert.equal(record.querySelectorAll('dd')[1].textContent, 'Default graph');
    table.dispose();
});

test('the arrow keys scroll a focused table box that is wider than its column, and nothing else', async () => {
    const workbench = loadWorkbench();
    const { table } = standaloneTable(workbench, [[iri('http://example.org/a')]], ['value']);
    await table.render();
    const box = table.tableWrap;
    box.scrollLeft = 0;
    box.scrollWidth = 1000;
    box.clientWidth = 400;
    box.trigger('keydown', { key: 'ArrowRight' });
    assert.equal(box.scrollLeft, 40, 'ArrowRight scrolls by one step');
    box.trigger('keydown', { key: 'ArrowLeft' });
    assert.equal(box.scrollLeft, 0, 'ArrowLeft scrolls back');
    box.scrollLeft = 590;
    box.trigger('keydown', { key: 'ArrowRight' });
    assert.equal(box.scrollLeft, 600, 'the step stops at the right edge');
    box.trigger('keydown', { key: 'ArrowRight', target: box.querySelector('a') });
    assert.equal(box.scrollLeft, 600, 'keys from a link inside the box are left to the browser');
    box.scrollWidth = 400;
    box.scrollLeft = 0;
    box.trigger('keydown', { key: 'ArrowRight' });
    assert.equal(box.scrollLeft, 0, 'a box that fits does not scroll');
    table.dispose();
    box.scrollWidth = 1000;
    box.trigger('keydown', { key: 'ArrowRight' });
    assert.equal(box.scrollLeft, 0, 'a disposed table stops listening');
});

test('the Remove preview is the shared result table, with Graph and Default graph', async () => {
    const workbench = loadWorkbench();
    const model = {
        viewId: 'remove', vars: ['context'], rows: [[iri('http://example.org/g')]], rowCount: 1, rowStart: 0,
        namespaceMap: { 'ex:': 'http://example.org/' }, links: [], metadata: {}
    };
    model.removePreview = { state: 'shown', rows: [
        [iri('http://example.org/s'), iri('http://example.org/p'), { kind: 'literal', value: 'o' }, null],
        [iri('http://example.org/s'), iri('http://example.org/q'), { kind: 'literal', value: '1', datatype: XSD + 'integer' },
            iri('http://example.org/g')]
    ], truncated: false, timedOut: false, message: '', controller: null, generation: 1 };
    const page = await renderPageResultTables(workbench, model, context);
    assert.deepEqual(page.hosts.map(host => host.getAttribute('data-workbench-result-table')), ['remove-preview']);
    assert.deepEqual(page.headers('remove-preview'), ['Subject', 'Predicate', 'Object', 'Graph']);
    const host = page.host('remove-preview');
    const graphs = host.querySelectorAll('td').filter(cell => cell.getAttribute('data-label') === 'Graph');
    assert.deepEqual(graphs.map(cell => cell.textContent.replace('↗', '')), ['Default graph', 'ex:g']);
    assert.ok(host.classList.contains('query-result-layout') && host.classList.contains('query-result-embedded'),
        'the preview is styled exactly like the Query page results');
});

test('a page keeps its result tables across renders and disposes the ones it no longer shows', async () => {
    const workbench = loadWorkbench();
    const rows = Array.from({ length: 3 }, (_unused, index) => [iri('urn:s'), iri('urn:p' + index), iri('urn:o'), null]);
    const model = { viewId: 'explore', vars: ['subject', 'predicate', 'object', 'context'], rows, rowCount: rows.length,
        rowStart: 0, namespaceMap: {}, links: [], metadata: { 'explore-resource': '<urn:s>' } };
    const page = await renderPageResultTables(workbench, model, context);
    const outgoing = page.host('explore-outgoing');
    assert.ok(outgoing, 'rows about the resource are grouped');
    const table = outgoing.querySelector('table.data');
    workbench.views.render(page.mount, model, context, page.runtime);
    await settle();
    const again = resultTableHosts(workbench.views.outletOf(page.mount).template);
    assert.equal(again[0], outgoing, 'rendering the page again keeps the table host');
    assert.equal(outgoing.querySelector('table.data'), table, 'and the table in it');

    // Explore's Display pane switches the datatype tags of every table of the page.
    const handlers = [];
    (function find(template) {
        if (Array.isArray(template)) { template.forEach(find); return; }
        if (template && Array.isArray(template.strings)) {
            template.strings.forEach((part, index) => {
                if (/id="explore-show-datatypes"[^>]*@change=$/.test(part.replace(/\s+/g, ' '))) {
                    handlers.push(template.values[index]);
                }
            });
            template.values.forEach(find);
        }
    })(workbench.views.outletOf(page.mount).template);
    assert.equal(handlers.length, 1, 'the Show datatypes checkbox has a change handler');
    handlers[0]({ currentTarget: { checked: false } });
    await settle();
    assert.equal(outgoing.querySelectorAll('.rdf-datatype').length, 0);

    workbench.views.releasePage(model);
    outgoing.querySelector('.query-result-table-wrap').scrollWidth = 1000;
    outgoing.querySelector('.query-result-table-wrap').trigger('keydown', { key: 'ArrowRight' });
    assert.equal(outgoing.querySelector('.query-result-table-wrap').scrollLeft || 0, 0,
        'releasing the page disposes its tables');
});
